import { readEntries, summarize, wrapActorPreCreate, wrapPreCreate } from "../../lib/compendium-copy/index.mjs";
import { fromFactory } from "../../kernel/wrap.mjs";
import { PATCH_ID, createEntries, outdatedItemIds } from "./domain.mjs";

/** The known entries, with the added effects' _id generated by foundry.utils.randomID. */
const entriesOf = (ctx) => createEntries(() => ctx.platform.utils.randomID());

export function isNeeded() {
  return { bug: "unknown", confidence: "low", evidence: "compendium data can only be read after ready" };
}

/** @param {import("../../kernel/feature.mjs").FeatureContext} ctx */
export async function lateProbe(ctx) {
  try {
    return summarize(await readEntries(entriesOf(ctx), ctx.platform.documents.packs()));
  } catch (error) {
    ctx.log.warn("probe failed", error);
    return undefined;
  }
}

/** Marks, on the actor sheet, the items to remove and add again to receive the corrected data. */
function outdatedMarker(ctx, entries) {
  return function markOutdated(app, html) {
    try {
      const actor = app?.actor ?? app?.document;
      const root = rootOf(html);
      if (!actor?.items || !root?.querySelectorAll) return;
      const tooltip = ctx.platform.i18n.localize("T20CP.RaceData.Outdated");
      for (const id of outdatedItemIds(actor.items, entries)) {
        for (const row of root.querySelectorAll(`[data-item-id="${id}"]`)) markRow(row, tooltip);
      }
    } catch (error) {
      ctx.log.warn("outdated marker skipped", error);
    }
  };
}

const rootOf = (html) => (globalThis.HTMLElement && html instanceof HTMLElement ? html : html?.[0]);

function markRow(row, tooltip) {
  if (row.querySelector(".t20cp-outdated")) return;
  const icon = document.createElement("i");
  icon.className = "fa-solid fa-triangle-exclamation t20cp-outdated";
  icon.dataset.tooltip = tooltip;
  icon.setAttribute("aria-label", tooltip);
  const anchor = row.querySelector(".item-name label, a.item-control");
  if (anchor) anchor.after(icon);
  else row.append(icon);
}

/** @param {import("../../kernel/feature.mjs").FeatureContext} ctx */
export function install(ctx) {
  const entries = entriesOf(ctx);
  const item = ctx.platform.classes.item?.prototype;
  if (typeof item?._preCreate === "function") {
    ctx.wrap(item, "_preCreate", fromFactory((original) => wrapPreCreate(original, "Item", entries, PATCH_ID)));
  }
  const actor = ctx.platform.classes.actor?.prototype;
  if (typeof actor?._preCreate === "function") {
    ctx.wrap(actor, "_preCreate", fromFactory((original) => wrapActorPreCreate(original, entries, PATCH_ID)));
  }
  ctx.hooks.on("renderActorSheetT20", outdatedMarker(ctx, entries));
}
